package dk.jamesbabz.madkursus.outbound.recipe.details;
import java.util.UUID;import jakarta.persistence.*;import lombok.*;import dk.jamesbabz.madkursus.service.models.RecipeStructuredInstruction;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;
@Entity @Table(name="recipe_preparation_steps") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class RecipePreparationStepEntity{@Id private UUID id;@ManyToOne(optional=false)@JoinColumn(name="recipe_id")private RecipeEntity recipe;private String instruction;@JdbcTypeCode(SqlTypes.JSON)private RecipeStructuredInstruction structuredInstruction;private int sortOrder;public RecipePreparationStepEntity(UUID id,String instruction,int sortOrder){this(id,instruction,null,sortOrder);}public RecipePreparationStepEntity(UUID id,String instruction,RecipeStructuredInstruction structured,int sortOrder){this.id=id;this.instruction=instruction;structuredInstruction=structured;this.sortOrder=sortOrder;}void setRecipe(RecipeEntity value){recipe=value;}}
